import{_ as a,o as t,c as s,ag as r}from"./chunks/framework.DqVSm8kp.js";const p=JSON.parse('{"title":"Decouvert avec LLMxRay","description":"","frontmatter":{},"headers":[],"relativePath":"fr/community/showcase.md","filePath":"fr/community/showcase.md"}'),n={name:"fr/community/showcase.md"};function o(i,e,l,u,c,d){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="decouvert-avec-llmxray" tabindex="-1">Decouvert avec LLMxRay <a class="header-anchor" href="#decouvert-avec-llmxray" aria-label="Permalink to &quot;Decouvert avec LLMxRay&quot;">​</a></h1><p>Une selection de decouvertes interessantes, de comportements surprenants et d&#39;observations precieuses faites par la communaute grace a LLMxRay.</p><h2 id="comment-soumettre" tabindex="-1">Comment soumettre <a class="header-anchor" href="#comment-soumettre" aria-label="Permalink to &quot;Comment soumettre&quot;">​</a></h2><p>Vous avez trouve quelque chose d&#39;interessant ? Nous serions ravis de le mettre en avant.</p><ol><li>Ouvrez une issue <a href="https://github.com/LogneBudo/llmxray/issues/new?template=showcase-submission.yml" target="_blank" rel="noreferrer">Soumission Vitrine</a></li><li>Remplissez le formulaire structure : ce que vous avez trouve, quels modeles, comment reproduire</li><li>Incluez des captures d&#39;ecran de LLMxRay si possible</li><li>Nous examinerons votre soumission et l&#39;ajouterons a cette page</li></ol><hr><h2 id="decouvertes-mises-en-avant" tabindex="-1">Decouvertes mises en avant <a class="header-anchor" href="#decouvertes-mises-en-avant" aria-label="Permalink to &quot;Decouvertes mises en avant&quot;">​</a></h2><h3 id="effet-de-seuil-de-la-temperature-sur-la-generation-de-code" tabindex="-1">Effet de seuil de la temperature sur la generation de code <a class="header-anchor" href="#effet-de-seuil-de-la-temperature-sur-la-generation-de-code" aria-label="Permalink to &quot;Effet de seuil de la temperature sur la generation de code&quot;">​</a></h3><p><strong>Contributeur :</strong> LogneBudo | <strong>Modeles :</strong> Mistral 7B | <strong>Date :</strong> Mars 2026</p><p>En utilisant la fonctionnalite Compare avec le preset Temperature Sweep, nous avons constate que Mistral 7B produit du code Python nettement plus precis a une temperature de 0.2 qu&#39;a 0.7. A 0.7, le modele introduit des noms de variables creatifs mais incorrects et hallucine occasionnellement des methodes d&#39;API. La coloration de confiance des tokens dans Chat Diagnostics a rendu cette incertitude visible — les tokens de la sortie a 0.7 affichaient systematiquement une confiance plus faible (davantage orange) autour des appels de fonctions.</p><h3 id="la-profondeur-de-reflexion-de-deepseek-r1-varie-selon-le-type-de-question" tabindex="-1">La profondeur de reflexion de DeepSeek-R1 varie selon le type de question <a class="header-anchor" href="#la-profondeur-de-reflexion-de-deepseek-r1-varie-selon-le-type-de-question" aria-label="Permalink to &quot;La profondeur de reflexion de DeepSeek-R1 varie selon le type de question&quot;">​</a></h3><p><strong>Contributeur :</strong> LogneBudo | <strong>Modeles :</strong> DeepSeek-R1 7B | <strong>Date :</strong> Mars 2026</p><p>L&#39;onglet Reasoning a revele que les blocs <code>&lt;think&gt;</code> de DeepSeek-R1 sont considerablement plus longs pour les problemes mathematiques (GSM8K) que pour le rappel factuel (TruthfulQA). Sur GSM8K, le modele effectue en moyenne 12 a 15 etapes de raisonnement avec verification arithmetique explicite. Sur TruthfulQA, il utilise generalement 2 a 3 etapes avant de s&#39;engager sur une reponse. Cela etait visible dans les resultats de Benchmark — GSM8K presentait un TTFT plus eleve mais aussi une meilleure precision lorsque le budget de reflexion n&#39;etait pas plafonne.</p><h3 id="impact-de-la-quantification-sur-la-precision-des-benchmarks" tabindex="-1">Impact de la quantification sur la precision des benchmarks <a class="header-anchor" href="#impact-de-la-quantification-sur-la-precision-des-benchmarks" aria-label="Permalink to &quot;Impact de la quantification sur la precision des benchmarks&quot;">​</a></h3><p><strong>Contributeur :</strong> LogneBudo | <strong>Modeles :</strong> Llama 3.2 3B (Q4_0 vs Q8_0) | <strong>Date :</strong> Mars 2026</p><p>L&#39;execution de la meme suite ARC-Challenge sur Llama 3.2 en Q4_0 et Q8_0 via la page Benchmark a montre une baisse de precision de 4.2 % en Q4_0. La ventilation par categorie a revele que cette baisse se concentrait sur les questions de physique (chute de 7.1 %) tandis que les questions de biologie etaient a peine affectees (0.8 % de baisse). Les distributions de logprob ont confirme que le Q4_0 etait globalement moins confiant, mais l&#39;ecart de confiance se creusait specifiquement sur les questions necessitant un raisonnement numerique en plusieurs etapes.</p><hr><p><em>Vous souhaitez voir votre decouverte ici ? <a href="https://github.com/LogneBudo/llmxray/issues/new?template=showcase-submission.yml" target="_blank" rel="noreferrer">Soumettez une issue Vitrine</a>.</em></p>',18)])])}const h=a(n,[["render",o]]);export{p as __pageData,h as default};
